   211	/**
   212	 * Record many observe events in ONE binary spawn via
   213	 * `observe record --stdin` (JSON Lines). Per-event spawns cost a process
   214	 * start plus a bolt open each — a session start injecting dozens of
   215	 * sources paid seconds for what is one write transaction. Falls back to
   216	 * per-event recording when the binary predates --stdin. Fire-and-forget.
   217	 */
   218	export function recordObserveEventsBatch(
   219	  binary: string,
   220	  cwd: string,
   221	  events: ObserveBatchEvent[],
   222	): void {
   223	  if (events.length === 0) return;
   224	  try {
   225	    const input = events.map((e) => JSON.stringify(e)).join("\n") + "\n";
   226	    execFileSync(binary, ["observe", "record", "--stdin"], {
   227	      cwd,
   228	      input,
   229	      timeout: 10000,
   230	      stdio: ["pipe", "pipe", "pipe"],
   231	    });
   232	    debug(SOURCE, `Observe batch: recorded ${events.length} event(s)`);
   233	  } catch (err) {
   234	    debug(SOURCE, `Observe batch failed (${err}); falling back to per-event`);
   235	    for (const e of events) {
   236	      recordObserveEvent(binary, cwd, e);
   237	    }
   238	  }
   239	}
