   277	/**
   278	 * Record an arbitrary observe event via `aide observe record`.
   279	 * Prefer `emitInjectionEvent` for `kind=injection` callers — this raw
   280	 * recorder is reserved for non-injection kinds (e.g. `hook` user_prompt
   281	 * events). Fire-and-forget.
   282	 */
   283	export function recordObserveEvent(
   284	  binary: string,
   285	  cwd: string,
   286	  opts: {
   287	    kind: string;
   288	    name: string;
   289	    category?: string;
   290	    subtype?: string;
   291	    tokens?: number;
   292	    saved?: number;
   293	    file?: string;
   294	    session?: string;
   295	    attrs?: Record<string, string>;
   296	  },
   297	): void {
   298	  try {
   299	    const args = [
