   301	      "record",
   302	      `--kind=${opts.kind}`,
   303	      `--name=${opts.name}`,
   304	    ];
   305	    if (opts.category) args.push(`--category=${opts.category}`);
   306	    if (opts.subtype) args.push(`--subtype=${opts.subtype}`);
   307	    if (opts.tokens !== undefined) args.push(`--tokens=${opts.tokens}`);
   308	    if (opts.saved !== undefined) args.push(`--saved=${opts.saved}`);
   309	    if (opts.file) args.push(`--file=${opts.file}`);
   310	    if (opts.session) args.push(`--session=${opts.session}`);
   311	    for (const [k, v] of Object.entries(opts.attrs ?? {})) {
