   218	// observeBatchLine is one JSON Lines record for `observe record --stdin`.
   219	type observeBatchLine struct {
   220		Timestamp *time.Time        `json:"ts,omitempty"`
   221		Kind      string            `json:"kind"`
   222		Name      string            `json:"name"`
   223		Category  string            `json:"category,omitempty"`
   224		Subtype   string            `json:"subtype,omitempty"`
   225		Tokens    int               `json:"tokens,omitempty"`
   226		Saved     int               `json:"saved,omitempty"`
   227		File      string            `json:"file,omitempty"`
   228		Session   string            `json:"session,omitempty"`
   229		Error     string            `json:"error,omitempty"`
   230		Attrs     map[string]string `json:"attrs,omitempty"`
   231	}
   232	
   233	// cmdObserveRecordBatch ingests JSON Lines from stdin under ONE store
   234	// open. Hooks that emit an event per injected source were paying a full
   235	// binary spawn + bolt open each — at session start that multiplied into
   236	// seconds. Malformed lines are skipped and counted, never fatal.
   237	func cmdObserveRecordBatch(dbPath string) error {
   238		backend, err := NewBackend(dbPath)
   239		if err != nil {
   240			return err
   241		}
   242		defer backend.Close()
   243	
   244		recorded, skipped := 0, 0
   245		scanner := bufio.NewScanner(os.Stdin)
   246		scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
   247		for scanner.Scan() {
   248			line := strings.TrimSpace(scanner.Text())
   249			if line == "" {
   250				continue
   251			}
   252			var l observeBatchLine
   253			if err := json.Unmarshal([]byte(line), &l); err != nil || l.Kind == "" || l.Name == "" || (l.Timestamp != nil && l.Timestamp.IsZero()) {
   254				skipped++
   255				continue
   256			}
   257			ev := &observe.Event{
   258				Kind:        observe.Kind(l.Kind),
   259				Name:        l.Name,
   260				Category:    l.Category,
   261				Subtype:     l.Subtype,
   262				Tokens:      l.Tokens,
   263				TokensSaved: l.Saved,
   264				FilePath:    l.File,
   265				SessionID:   l.Session,
   266				Error:       l.Error,
   267				Attrs:       l.Attrs,
   268			}
   269			if l.Timestamp != nil {
   270				ev.Timestamp = *l.Timestamp
   271			}
   272			if err := backend.Store().AddObserveEvent(ev); err != nil {
   273				skipped++
   274				continue
   275			}
   276			recorded++
   277		}
   278		if err := scanner.Err(); err != nil {
   279			return fmt.Errorf("reading stdin: %w", err)
   280		}
   281		fmt.Printf("recorded %d event(s)", recorded)
   282		if skipped > 0 {
   283			fmt.Printf(", skipped %d", skipped)
   284		}
   285		fmt.Println()
   286		return nil
   287	}
   288	
   289	// cmdObserveRecord emits observe events from the CLI: one event from
   290	// flags, or a batch of JSON Lines from stdin with --stdin. Used by hooks
   291	// (skill-injector, session-start) to record per-source injection events.
   292	func cmdObserveRecord(dbPath string, args []string) error {
   293		if hasFlag(args, "--stdin") {
   294			return cmdObserveRecordBatch(dbPath)
   295		}
   296		kind := parseFlag(args, "--kind=")
   297		name := parseFlag(args, "--name=")
   298		if kind == "" || name == "" {
   299			return fmt.Errorf("--kind and --name are required")
   300		}
"}

