   136	// AddObserveEvent persists one observe.Event. Populates ID and Timestamp if
   137	// the caller left them empty (e.g., external RecordEvent RPC, observe record
   138	// CLI) — the in-process Recorder always sets them, but defending here keeps
   139	// the bolt layer from rejecting the write with "key required".
   140	func (s *BoltStore) AddObserveEvent(e *observe.Event) error {
   141		// New measurements use one estimator, independently of legacy handler estimates.
   142		if e.Attrs["accounting_version"] == "1" {
